import{_ as t,o,c as a,a3 as i}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Analyze","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Analyze | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/cli/analyze"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/cli/analyze"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/analyze"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/analyze"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/analyze"}]]},"headers":[],"relativePath":"clice/cli/analyze.md","filePath":"en/clice/cli/analyze.md","lastUpdated":1791156255000}'),n={name:"clice/cli/analyze.md"};function d(s,e,l,r,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="analyze" tabindex="-1">Analyze <a class="header-anchor" href="#analyze" aria-label="Permalink to &quot;Analyze&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>clice analyze</code> reads the persisted index and reports facts a coding agent turns into refactoring decisions. It never builds or times anything: it describes the code, and the agent — with the code at hand — decides what to change. Like <code>clice query</code>, it reads the index <code>clice index</code> builds and prints JSON on stdout.</p><p><strong>Usage</strong>: <code>clice analyze &lt;analysis&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [options]</code></p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><p><code>clice analyze modules</code> describes how the directories of a program depend on each other, as the input for partitioning it into C++20 named modules: which cycles stand in the way, which few entities each cycle hangs on, which headers belong elsewhere, and which constructs a mechanical rewrite into modules cannot carry over.</p><p>Every file in the scope belongs to a module, by default its directory. A module depends on another when one of its files names an entity a file of the other provides: a spelled name, a name a macro expansion produces in that file, or the template an explicit specialization specializes. The file providing an entity is a header defining it, else a header declaring it, else the source defining it. A dependency from a header is an interface edge, which would become an import of the module&#39;s interface; one only from sources is an implementation edge, which never closes a cycle because an implementation unit may import a module above it. Textual fragments such as <code>.inc</code> and <code>.def</code> files count as part of the files including them. A header only its own module&#39;s sources use, directly or through other such headers, is an internal partition: it adds nothing to the module&#39;s interface, and none of its dependencies are interface edges.</p><ul><li><code>--scope &lt;glob,...&gt;</code> analyzes only the files the globs match, as workspace-relative paths; by default every indexed file under the workspace outside a dot directory.</li><li><code>--depth &lt;n&gt;</code> names a file&#39;s default module by the first <code>n</code> segments of its directory instead of all of them.</li><li><code>--partition &lt;file&gt;</code> assigns modules by globs, first match wins: <code>{&quot;modules&quot;: [{&quot;name&quot;: &quot;core&quot;, &quot;files&quot;: [&quot;src/support/**&quot;, &quot;src/vfs/**&quot;]}]}</code>. Files no glob claims keep their directory module.</li><li><code>--move &lt;path&gt;=&lt;module&gt;,...</code> and <code>--merge &lt;module&gt;+&lt;module&gt;[+...],...</code> evaluate a hypothetical change without making it.</li><li><code>--move-entity &lt;name&gt;=&lt;header&gt;,...</code> evaluates moving a declaration, with its members and what their definitions name, to another header, existing or new; <code>#&lt;id&gt;</code> from the <code>edge</code> view picks one of several overloads.</li><li><code>--annotation &lt;file&gt;,...</code> and <code>--churn-since &lt;date&gt;</code> weigh the results; see <a href="#annotations">annotations</a>.</li><li><code>--view &lt;view&gt;</code> chooses the answer, <code>overview</code> by default.</li></ul><table tabindex="0"><thead><tr><th>View</th><th>Answers</th></tr></thead><tbody><tr><td><code>overview</code></td><td>the modules by layer, the edges with sample entities, the cycles with the lightest set of edges whose removal breaks each, header cycles inside a module, the number of internal partitions, the deepest import chain, rebuild totals, hotspots, move and split candidates, and obstacle counts</td></tr><tr><td><code>edge --from &lt;module&gt; --to &lt;module&gt;</code></td><td>every entity the edge carries, with its id, owner and the <code>file:line</code> of each use</td></tr><tr><td><code>module --module &lt;module&gt;</code></td><td>each file&#39;s dependencies and dependents by module, the module&#39;s internal partitions, and its other headers grouped by the modules using them — the lines a directory splits along</td></tr><tr><td><code>file --file &lt;path&gt;</code></td><td>what the file names by module, who names its entities, and its annotations</td></tr><tr><td><code>obstacles</code></td><td>every construct listed below</td></tr><tr><td><code>macros</code></td><td>macros used outside the file defining them, by module: imports carry no macros, so each reaches its users through a textual header</td></tr><tr><td><code>impact</code></td><td>per header, the units an edit to it rebuilds today and under the partition, and whether it is an internal partition</td></tr></tbody></table><p>The overview&#39;s hotspots, move candidates and split candidates are capped by <code>--limit</code> (20 by default); modules, edges and cycles are always complete.</p><p>A move candidate is a header whose users all sit in one other module and that, together with the sources implementing it and the other headers those implement, names nothing of its own module and is named by nothing else there, short of the whole module; those files are listed to move along. A split candidate is a header whose entities fall into groups no consuming module shares, each listed as <code>name:line</code>, the first ten by line, with a <code>count</code> of all.</p><h3 id="obstacles" tabindex="-1">Obstacles <a class="header-anchor" href="#obstacles" aria-label="Permalink to &quot;Obstacles&quot;">​</a></h3><ul><li>A header the index holds several row variants of reads differently depending on what includes it; compiled once as a module interface it would keep one reading. <code>declarationsDiffer</code> marks variants declaring different entities, a real configuration dependence, and only those count in the overview; <code>unstable</code> names what only some variants name, such as the overloads a template&#39;s dependent call finds where it is included.</li><li>A header testing a macro in a preprocessor condition without including its definition reads differently compiled alone, silently (<code>contextMacros</code>); one expanding such a macro fails to compile alone until it includes the definition (<code>borrowedMacros</code>).</li><li>A <code>static</code> or anonymous-namespace entity of a header that another file uses, or that the header&#39;s own inline code uses, is local to one translation unit once the header is a module interface.</li><li>A forward or friend declaration of an entity another module provides declares a different entity inside a module unit; one of a third-party entity attaches it to the wrong module. <code>unused</code> marks those the file never names, which can simply go.</li><li>A declaration in one module&#39;s header whose definition sits in another module&#39;s source, and an entity several headers define.</li><li>A macro a header defines that a third-party header reads (<code>configuringMacros</code>) has to stay ahead of that header&#39;s include in the global module fragment.</li><li>A header specializing a third-party template for arguments it does not provide itself (<code>implicitProviders</code>) is used by every instantiation without being named, so no edge records those users; it stays where every instantiating unit can import it.</li><li>Explicit specializations of a template from another module are listed too: they are legal, but reachable only where their module is imported.</li></ul><h3 id="rebuild-estimates" tabindex="-1">Rebuild estimates <a class="header-anchor" href="#rebuild-estimates" aria-label="Permalink to &quot;Rebuild estimates&quot;">​</a></h3><p>Editing a module&#39;s interface recompiles every unit of every module importing it, directly or through other interfaces: a module&#39;s compiled interface records a hash of each one it imports. <code>impact</code> and the overview&#39;s totals compare that, counted in translation units, with the units an edit to the header rebuilds today. An edit to an internal partition rebuilds only the sources reaching it, and an edit to a source rebuilds one unit either way. The estimates are conservative and count only the program&#39;s sources.</p><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>An annotation is a named number per file that weighs the results, the way a profile weighs an optimizer&#39;s choices; every result stays meaningful without any.</p><ul><li><code>churn</code> is how often a file changes: by default the commits of the last six months that touched it, from <code>git log</code> (<code>--churn-since &lt;date&gt;</code> takes any <code>git log --since</code> value; an empty value leaves it out). Hotspots and rebuild totals multiply by it.</li><li><code>compile_time</code> is what rebuilding a translation unit costs. Without it every unit counts as one.</li></ul><p>An annotation file is <code>{&quot;name&quot;: &quot;compile_time&quot;, &quot;unit&quot;: &quot;s&quot;, &quot;values&quot;: {&quot;src/main.cpp&quot;: 4.2}}</code> with workspace-relative paths; one named like a computed annotation replaces it.</p><h2 id="answers" tabindex="-1">Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;Answers&quot;">​</a></h2><p>Every answer is one JSON object, or <code>{&quot;error&quot;: &quot;...&quot;, &quot;stale&quot;: [...]}</code> with exit code 1 when the question cannot be answered (no index, an unknown module or file, an invalid glob), or 2 when the arguments do not parse; an index missing some units fails with those units in <code>stale</code>.</p>',21)])])}const p=t(n,[["render",d]]);export{m as __pageData,p as default};
